INSERT INTO enrollment_archive (enrollment_id, patient_id, trial_id, enrollment_status, start_date, end_date, duration_days, archived_at, archive_reason, principal_investigator)
SELECT enrollment_id, patient_id, trial_id, enrollment_status, start_date, end_date, end_date - start_date, CURRENT_TIMESTAMP, 'trial_completed', principal_investigator
FROM trial_enrollments
WHERE enrollment_status = 'completed' AND end_date < CURRENT_DATE;

SELECT * FROM enrollment_archive ORDER BY patient_id, trial_id;
